package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden represents a window-box garden with two rows of cups,
// assigned to children in alphabetical order of their names.
type Garden struct {
	rows     [2]string
	children map[string]int // child name -> index of their pair of cups
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses a diagram of the form "\n<row1>\n<row2>" and assigns
// cups to children alphabetically. It returns an error if the diagram is
// malformed or the children contain duplicates.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[1]) != len(rows[2]) {
		return nil, errors.New("rows must be the same length")
	}
	if len(rows[1])%2 != 0 {
		return nil, errors.New("number of cups must be even")
	}
	for _, r := range rows[1] + rows[2] {
		if _, ok := plantNames[r]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", r)
		}
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	indexes := make(map[string]int, len(sorted))
	for i, name := range sorted {
		if _, dup := indexes[name]; dup {
			return nil, fmt.Errorf("duplicate name %q", name)
		}
		indexes[name] = i
	}
	if len(sorted)*2 > len(rows[1]) {
		return nil, errors.New("not enough cups for all children")
	}
	return &Garden{
		rows:     [2]string{rows[1], rows[2]},
		children: indexes,
	}, nil
}

// Plants returns the four plants belonging to the named child: two from
// the upper row and two from the lower row, left to right. The boolean
// result is false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	index, ok := g.children[child]
	if !ok {
		return nil, false
	}
	start := 2 * index
	plants := make([]string, 4)
	for i, row := range g.rows {
		for j := 0; j < 2; j++ {
			plants[2*i+j] = plantNames[rune(row[start+j])]
		}
	}
	return plants, true
}
```

