	}
	return &Garden{
		rows:     [2]string{rows[1], rows[2]},
		children: indexes,
	}, nil
}

// Plants returns the four plants belonging to the named child: two from
// the upper row and two from the lower row, left to right. The boolean
// result is false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	index, ok := g.children[child]
	if !ok {
		return nil, false
	}
	start := 2 * index
	plants := make([]string, 4)
	for i, row := range g.rows {
		plants[2*i] = plantNames[rune(row[start])]
		plants[2*i+1] = plantNames[rune(row[start+1])]
	}
	return plants, true
}

